def compile_program(chars, effects, script, base_atk, *, defense=0, core_ratio=0, core_bonus=1, combat=None, allies=None, cover_sync=True, native_landing=False, enemy_code=None, geometry=None, burst_references=None, enemy_targeting=None, world_frame=False, world_notice_names=(), allied_seed=19, focus_aim_layer2=False, native_snapshot_logging=False, native_equipment_carriers=False):
    if type(native_equipment_carriers) is not bool:raise ValueError('Explicit native equipment carrier policy must be boolean')
    import detail_gpu as legacy
    from portable_stack_specs import plan as stack_plan,operation as stack_operation,value as stack_value,pack_metadata as pack_stack_metadata
    check_schema()
    if type(world_frame) is not bool:raise ValueError("Invalid world-frame trigger policy")
    if not isinstance(world_notice_names,tuple) or any(n!='target_spawn' for n in world_notice_names) or world_notice_names and not world_frame:raise ValueError("Invalid world notice namespace")
    if type(native_snapshot_logging) is not bool:raise ValueError("Native snapshot logging requires a literal boolean")
    effects = list(effects)
    if type(focus_aim_layer2) is not bool or focus_aim_layer2 and (not world_frame or combat is None):raise ValueError('Focus aiming requires a literal private-world policy')
    hit_critical=any('trigger_hit_crit' in e.get('trigger',{}).get('condition',[]) for e,_ in effects)
    if hit_critical and (not world_frame or combat is None or not native_landing):
        raise UnsupportedPortable('Hit-critical context requires native combat world landing')
    if not 1<=len(effects)<=L['DEFINITIONS']:raise UnsupportedPortable('Portable definition capacity exceeded')
    if any(e.get('stat')=='lifesteal_pct' for e,_ in effects) and (not native_landing or combat is None):raise UnsupportedPortable('Lifesteal requires native landing phases')
    for eff, owner in effects:
        try:validate_effect(eff,combat=combat,world_frame=world_frame)
        except UnsupportedPortable as error:
            # Keep the original category/message; expose which authored effect
            # caused fallback instead of returning an anonymous compiler gap.
            error.effect_context=dict(character=owner,effect=eff.get('name',''),
                stat=eff.get('stat',''),target=copy.deepcopy(eff.get('target')))
            raise
    from portable_source_specs import validate_sources,pack as pack_source
